<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>2048</title>
<style>
  :root {
    color-scheme: dark;
    --bg: #12151d;
    --panel: #1d2330;
    --cell: #2b3343;
    --text: #f4f7fb;
    --muted: #aab5c8;
    --accent: #5b8cff;
  }

  * { box-sizing: border-box; }

  body {
    margin: 0;
    min-height: 100vh;
    display: grid;
    place-items: center;
    background: radial-gradient(circle at top, #252d3d, var(--bg) 65%);
    color: var(--text);
    font-family: Arial, Helvetica, sans-serif;
  }

  .game-shell {
    width: min(92vw, 460px);
    padding: 22px;
    border-radius: 18px;
    background: rgba(29, 35, 48, 0.9);
    box-shadow: 0 18px 50px rgba(0, 0, 0, 0.38);
  }

  header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 14px;
    margin-bottom: 18px;
  }

  h1 {
    margin: 0;
    font-size: 2.3rem;
    letter-spacing: 0.04em;
  }

  .score-wrap {
    text-align: center;
    background: #303a4d;
    border-radius: 10px;
    min-width: 100px;
    padding: 7px 12px;
  }

  .score-label {
    display: block;
    font-size: 0.68rem;
    color: var(--muted);
    letter-spacing: 0.12em;
  }

  #score {
    display: block;
    font-size: 1.35rem;
    font-weight: bold;
  }

  .controls {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 14px;
    color: var(--muted);
    font-size: 0.9rem;
  }

  #reset {
    border: 0;
    border-radius: 8px;
    background: var(--accent);
    color: white;
    font-weight: bold;
    padding: 9px 14px;
    cursor: pointer;
  }

  #reset:hover { background: #729cff; }
  #reset:active { transform: translateY(1px); }

  #board {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 10px;
    padding: 10px;
    background: #151b26;
    border-radius: 13px;
    aspect-ratio: 1;
  }

  .tile {
    display: grid;
    place-items: center;
    min-width: 0;
    border-radius: 9px;
    background: var(--cell);
    color: #fff;
    font-size: clamp(1.15rem, 6vw, 2rem);
    font-weight: 800;
    user-select: none;
  }

  .tile.empty { color: transparent; background: #283142; }
  .tile.v2 { background: #4a5870; }
  .tile.v4 { background: #526a83; }
  .tile.v8 { background: #476f9f; }
  .tile.v16 { background: #3b7db9; }
  .tile.v32 { background: #2c8aaf; }
  .tile.v64 { background: #24908f; }
  .tile.v128 { background: #7d6ac7; font-size: clamp(1rem, 5vw, 1.75rem); }
  .tile.v256 { background: #9b5fbd; font-size: clamp(1rem, 5vw, 1.75rem); }
  .tile.v512 { background: #bd557f; font-size: clamp(1rem, 5vw, 1.75rem); }
  .tile.v1024, .tile.v2048, .tile.large {
    background: #d07b3c;
    font-size: clamp(0.8rem, 4vw, 1.35rem);
  }
</style>
</head>
<body>
  <main class="game-shell">
    <header>
      <h1>2048</h1>
      <div class="score-wrap">
        <span class="score-label">SCORE</span>
        <span id="score">0</span>
      </div>
    </header>

    <div class="controls">
      <span>Use arrow keys to move</span>
      <button id="reset" type="button">New Game</button>
    </div>

    <div id="board" aria-label="2048 game board"></div>
  </main>

<script>
(() => {
  const SIZE = 4;
  let grid = [];
  let currentScore = 0;

  const boardElement = document.getElementById("board");
  const scoreElement = document.getElementById("score");
  const resetButton = document.getElementById("reset");

  function emptyGrid() {
    return Array.from({ length: SIZE }, () => Array(SIZE).fill(0));
  }

  function cloneGrid(source) {
    return source.map(row => row.slice());
  }

  function render() {
    boardElement.innerHTML = "";
    for (let row = 0; row < SIZE; row++) {
      for (let col = 0; col < SIZE; col++) {
        const value = grid[row][col];
        const tile = document.createElement("div");
        tile.className = "tile " + (value ? ("v" + value + (value > 2048 ? " large" : "")) : "empty");
        tile.textContent = value || "";
        tile.setAttribute("aria-label", value ? String(value) : "empty");
        boardElement.appendChild(tile);
      }
    }
    scoreElement.textContent = String(currentScore);
  }

  function addRandomTile() {
    const empty = [];
    for (let row = 0; row < SIZE; row++) {
      for (let col = 0; col < SIZE; col++) {
        if (grid[row][col] === 0) empty.push([row, col]);
      }
    }
    if (!empty.length) return false;
    const [row, col] = empty[Math.floor(Math.random() * empty.length)];
    grid[row][col] = Math.random() < 0.9 ? 2 : 4;
    return true;
  }

  function mergeLine(line) {
    const values = line.filter(value => value !== 0);
    const result = [];

    for (let i = 0; i < values.length; i++) {
      if (i + 1 < values.length && values[i] === values[i + 1]) {
        const merged = values[i] * 2;
        result.push(merged);
        currentScore += merged;
        i++;
      } else {
        result.push(values[i]);
      }
    }

    while (result.length < SIZE) result.push(0);
    return result;
  }

  function getLine(index, direction) {
    const line = [];
    for (let i = 0; i < SIZE; i++) {
      if (direction === "left") line.push(grid[index][i]);
      if (direction === "right") line.push(grid[index][SIZE - 1 - i]);
      if (direction === "up") line.push(grid[i][index]);
      if (direction === "down") line.push(grid[SIZE - 1 - i][index]);
    }
    return line;
  }

  function setLine(index, direction, line) {
    for (let i = 0; i < SIZE; i++) {
      if (direction === "left") grid[index][i] = line[i];
      if (direction === "right") grid[index][SIZE - 1 - i] = line[i];
      if (direction === "up") grid[i][index] = line[i];
      if (direction === "down") grid[SIZE - 1 - i][index] = line[i];
    }
  }

  function move(direction) {
    if (!["left", "right", "up", "down"].includes(direction)) return false;

    const before = cloneGrid(grid);

    for (let index = 0; index < SIZE; index++) {
      const mergedLine = mergeLine(getLine(index, direction));
      setLine(index, direction, mergedLine);
    }

    let changed = false;
    for (let row = 0; row < SIZE; row++) {
      for (let col = 0; col < SIZE; col++) {
        if (grid[row][col] !== before[row][col]) {
          changed = true;
          break;
        }
      }
      if (changed) break;
    }

    if (changed) addRandomTile();
    render();
    return changed;
  }

  function reset() {
    grid = emptyGrid();
    currentScore = 0;
    addRandomTile();
    addRandomTile();
    render();
  }

  function setBoard(arr) {
    if (!Array.isArray(arr) || arr.length !== SIZE ||
        arr.some(row => !Array.isArray(row) || row.length !== SIZE)) {
      throw new Error("setBoard expects a 4x4 array.");
    }

    grid = arr.map(row => row.map(value => {
      const number = Number(value);
      return Number.isFinite(number) && number > 0 ? number : 0;
    }));
    currentScore = 0;
    render();
  }

  window.game = {
    size: SIZE,
    reset,
    move,
    board: () => cloneGrid(grid),
    setBoard,
    score: () => currentScore
  };

  document.addEventListener("keydown", event => {
    const directions = {
      ArrowLeft: "left",
      ArrowRight: "right",
      ArrowUp: "up",
      ArrowDown: "down"
    };

    if (directions[event.key]) {
      event.preventDefault();
      move(directions[event.key]);
    }
  });

  resetButton.addEventListener("click", reset);
  reset();
})();
</script>
</body>
</html>
